        }
    </style>
</head>
<body class="">
    <script id="options-data-source" type="text/plain">
$1
    </script>

    <div class="container mx-auto px-3 py-4 max-w-3xl">
        <div class="status-block bg-dark rounded-2xl shadow-lg overflow-hidden border border-gray-700/30 theme-transition">
            <div class="p-4 border-b border-gray-700/20 theme-transition">
                <div class="flex justify-between items-center">
                    <div class="flex items-center text-gray-300">
                        <i class="fa fa-list-alt text-primary mr-2"></i>
                        <span class="font-medium">行动选项</span>
                    </div>
                    <div class="flex space-x-1">
                        <button data-theme="night" class="theme-btn active rounded-full border border-gray-700/50 w-7 h-7 flex items-center justify-center text-gray-400 hover:bg-primary/10" title="黑夜"><i class="fa fa-moon-o"></i></button>
                        <button data-theme="day" class="theme-btn rounded-full border border-gray-700/50 w-7 h-7 flex items-center justify-center text-gray-400 hover:bg-primary/10" title="白天"><i class="fa fa-sun-o"></i></button>
                    </div>
                </div>
            </div>

            <div class="p-4">
                <ul id="options-list" class="space-y-2"></ul>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            initThemeToggle();
            const renderer = new OptionsRenderer('options-data-source');
            renderer.init();
        });

        const triggerQuickReply = (text) => {
            if (typeof triggerSlash === 'function') {
                // 在SillyTavern/AI酒馆中，/send 用于直接发送消息，| /trigger 用于剧情推动（可选，根据平台调整）
                triggerSlash(`/send ${text}|/trigger`);
            } else {
                console.log('Would send:', text); // Edge浏览器控制台fallback
            }
        };

        function initThemeToggle() {
            const body = document.body;
            const buttons = document.querySelectorAll('.theme-btn');
            const savedTheme = localStorage.getItem('optionsTheme') || 'night';

            const switchToTheme = (theme) => {
                body.classList.toggle('day-mode', theme === 'day');
                buttons.forEach(btn => btn.classList.toggle('active', btn.dataset.theme === theme));
                localStorage.setItem('optionsTheme', theme);
            };

            buttons.forEach(btn => btn.addEventListener('click', () => switchToTheme(btn.dataset.theme)));
            switchToTheme(savedTheme);
        }

        class OptionsRenderer {
            constructor(dataSourceId) {
                this.dataSourceId = dataSourceId;
                this.optionsData = '';
            }

            init() {
                try {
                    const scriptEl = document.getElementById(this.dataSourceId);
                    this.optionsData = scriptEl.textContent.trim();
                    this.renderOptions();
                } catch (error) {
                    console.error('Render error:', error);
                    document.body.innerHTML = `<div class="text-red-500 p-4">Error: ${error.message}</div>`;
                }
            }

            renderOptions() {
                const optionsList = document.getElementById('options-list');
                optionsList.innerHTML = '';

                // 解析 [OptX:emoji] 文本 格式，提取干净的选项文本（忽略标签和emoji）
                const optionRegex = /\[Opt\d+:[^\]]+\]\s*(.+)/g;
                let match;
                let index = 1;

                while ((match = optionRegex.exec(this.optionsData)) !== null) {
                    const cleanOption = match[1].trim(); // 只取文本部分，用于发送
                    const fullOption = match[0].trim(); // 完整显示，包括 [OptX:emoji]

                    const li = document.createElement('li');
                    li.className = 'theme-transition';
                    li.innerHTML = `
                        <button class="option-btn w-full text-left text-gray-300 flex items-center justify-between" data-option="${cleanOption}">
                            <span>${fullOption}</span>
                            <i class="fa fa-arrow-right ml-2 text-primary/50"></i>
                        </button>
                    `;
                    li.addEventListener('click', (e) => {
                        const button = e.target.closest('button');
                        if (button) {
                            const optionText = button.dataset.option;
                            triggerQuickReply(optionText);
                            button.style.backgroundColor = 'rgba(157, 124, 245, 0.2)';
                            setTimeout(() => { button.style.backgroundColor = ''; }, 300);
                        }
                    });
                    optionsList.appendChild(li);
                    index++;
                }

                if (index === 1) {
                    optionsList.innerHTML = '<li class="text-gray-500 p-4">选项数据缺失...</li>';
                }
            }
        }
    </script>
</body>
</html>
