{
  "name": "卡巴内瑞",
  "definition": "卡巴内瑞是介于人类与怪物“卡巴内”之间的特殊存在。当人类被卡巴内咬伤后，若病毒在抵达大脑前被某种方式抑制，则个体不会完全变为卡巴内，而是成为既保留人类心智、又拥有卡巴内强大体能的卡巴内瑞。他们是被诅咒的生存形态，既不被人类同胞完全接纳，也被卡巴内视为攻击目标，在世界的缝隙中挣扎求存。",
  "core_characteristics": {
    "physiological_features": [
      {
        "title": "心脏与发光现象",
        "description": "与卡巴内类似，卡巴内瑞的心脏被钢铁皮膜覆盖并发出光芒，这既是强大生命力的源泉，也是其非人身份的象征。部分卡巴内瑞会佩戴特制的枷绳以抑制或隐藏心脏的光芒。"
      },
      {
        "title": "身体能力",
        "description": "具备远超普通人类的体能、速度、力量与恢复力。他们能够徒手与卡巴内搏斗，甚至能承受高温。"
      },
      {
        "title": "吸血需求",
        "description": "需要定期吸食人血以维持人类心智并抑制卡巴内病毒的侵蚀。如果长时间不吸血，将会逐渐失去理智，最终完全变为卡巴内。"
      }
    ],
    "abilities_and_limitations": [
      {
        "title": "战斗天赋",
        "description": "凭借卡巴内化的身体，卡巴内瑞在战斗中表现出极高的天赋，能够熟练运用各种武器，并常以寡敌众。在解除束缚（如特定的枷绳）后，其身体能力能在短时间内进一步提升。"
      },
      {
        "title": "病毒免疫",
        "description": "对卡巴内病毒具有免疫力，不会被再次感染而转变为卡巴内，但这并未减轻常人对他们的恐惧。"
      },
      {
        "title": "社会排斥",
        "description": "由于其暧昧的身份和可怖的力量，卡巴内瑞普遍遭受人类的恐惧、歧视和排斥，生存环境极为艰难。"
      }
    ]
  },
  "social_situation": "在卡巴内灾难爆发后的日之本，卡巴内瑞的存在本身就是一个尖锐的矛盾。他们拥有对抗怪物的力量，却被大多数人类视为与卡巴内无异的怪物。这种介于两个世界之间的尴尬身份，使得卡巴内瑞在寻求生存和认同的道路上充满了挑战与挣扎。"
}
